"""Deterministic original practice content; no source or learner records used."""
import json
from pathlib import Path
from math import pi

ROOT = Path(__file__).resolve().parents[1]
items = []
evidence = []
def fmt(n):
    return f'{n:.2f}'.replace('.', ',')

def calc(topic, slug, title, context, question, unit, formula, hint, cases, solve, derivation):
    for i, values in enumerate(cases, 1):
        result = solve(*values)
        assert result > 0
        options = [f'{fmt(result * factor)} {unit}' for factor in [1, .5, 2, 10]]
        assert len(set(options)) == 4
        correct = (len(items) + i) % 4
        options.insert(correct, options.pop(0))
        task_id = f'{topic}-{slug}-v1-{i}'
        items.append(dict(id=task_id, topicId=topic, title=f'{title} · Variante {i}',
            context=context.format(*[str(v).replace('.', ',') for v in values]),
            question=question + ' Runde das Endergebnis auf zwei Nachkommastellen.',
            options=options, correctIndex=correct,
            explanation=f'{derivation.format(*[str(v).replace(".", ",") for v in values])}\nErgebnis: {fmt(result)} {unit}. Rechne mit ungerundeten Zwischenwerten. Die Einheit des Ergebnisses muss zur gesuchten Größe passen. Es gilt ausschließlich das beschriebene Modell.',
            hint=hint, formula=formula, estimatedMinutes=4, level='Anwenden',
            sourceLabel='Eigene Modellaufgabe · Eigene Übungsaufgabe · Zahlenvariante · Version 1 · keine Originalprüfung'))
        evidence.append(dict(id=task_id, values=values, exactResult=result, unit=unit, displayedResult=options[correct], derivation=derivation))

